//autogenerated:yes
//nolint:revive,govet,errcheck
package marsh_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/marsh"
)

func TestEnum_MARSH_TYPE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.MARSH_TYPE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.MARSH_TYPE_MANAGER.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.MARSH_TYPE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.MARSH_TYPE_MANAGER, dec)
	})
}
